package ai.decisionos.aside;
import android.os.*;import android.app.*;import android.content.*;import android.webkit.*;import org.json.*;import java.util.concurrent.*;
/** Execute the actual board reader against authenticated/redirect/mismatched HTML fixtures. */
final class CampusExecutionChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;String gid="";try(GoalStore store=new GoalStore(i.getTargetContext())){
  for(String flow:new String[]{"notices","application","professor","course"})i.check(SchoolChatWork.campusExecutor(flow),"campus dispatch "+flow);for(String flow:new String[]{"concert","outfit","assignment","lecture"})i.check(!SchoolChatWork.campusExecutor(flow),"unsupported campus operation not claimed "+flow);
  gid=store.create("grades","REGRESSION_CAMPUS_EXECUTION","학교",0).optString("id");a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",gid).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity host=a;i.runOnMainSync(()->host.relay.stop());
  for(String mode:new String[]{"ok","mismatch","redirect"}){final WebView[] web={null};CountDownLatch done=new CountDownLatch(1);String[] result={null};String key="testBoards";
   String fixture="<script>window.fetch=async function(url){let id=new URL(url,location.href).searchParams.get('cabinetInstanceID');let board="+(mode.equals("mismatch")?"'9999'":"id")+";let html=\"<table><tr><td></td><td>1</td><td></td><td></td><td><a onclick=\\\"TitleClick('v','123','\"+board+\"')\\\">장학금 안내</a></td><td></td><td>2026.11.01</td><td></td></tr></table>\";return {ok:true,url:"+(mode.equals("redirect")?"'https://login.microsoftonline.com/'":"new URL(url,location.href).href")+",text:async()=>html}}</script>";
   i.runOnMainSync(()->{web[0]=new WebView(host);web[0].getSettings().setJavaScriptEnabled(true);web[0].setWebViewClient(new WebViewClient(){public void onPageFinished(WebView w,String url){w.evaluateJavascript(CampusBoardReader.start(key),v->new Handler(Looper.getMainLooper()).postDelayed(()->w.evaluateJavascript(CampusBoardReader.read(key),r->{result[0]=r;done.countDown();}),200));}});web[0].loadDataWithBaseURL("https://uspace.unist.ac.kr/",fixture,"text/html","UTF-8",null);});
   i.check(done.await(10,TimeUnit.SECONDS),"board reader completed "+mode);JSONObject data=new JSONObject(new JSONArray("["+result[0]+"]").getString(0));if(mode.equals("ok")){i.check(data.getString("state").equals("ok"),"three boards parsed");JSONArray rows=data.getJSONArray("rows");i.check(rows.length()==3,"all three board results");java.util.Set<String> ids=new java.util.HashSet<>();for(int n=0;n<rows.length();n++){ids.add(rows.getJSONObject(n).getString("board"));i.check(rows.getJSONObject(n).getString("date").equals("2026-11-01"),"posted date normalized");}i.check(ids.containsAll(java.util.Arrays.asList("1978","1126","1124")),"scholarship included");}else i.check(data.getString("state").equals("unverified")&&!data.has("rows"),"partial or login response rejected "+mode);
   i.runOnMainSync(()->web[0].destroy());
  }
  out.putString("stream","PASS "+i.checks+" campus execution and three-board parser checks\n");
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}finally{if(a!=null){final GoalAgentActivity host=a;i.runOnMainSync(host::finish);}if(!gid.isEmpty())try(GoalStore s=new GoalStore(i.getTargetContext())){s.deleteGoal(gid);}}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
